module tb_TopModule;
    reg clk;
    reg a;
    reg b;
    wire q;
    wire state;

    TopModule dut (
        .clk(clk),
        .a(a),
        .b(b),
        .q(q),
        .state(state)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        // Initialize inputs matching waveform
        a = 1; b = 0;
        #10; // at 10ns, clk=0, a=0, b=0
        a = 0; b = 0;

        // Let's trace waveform steps at each clock edge / half-cycle
        // time 15ns: clk posedge, a=0, b=0
        @(posedge clk); // 15ns
        #1;
        assert(state == 0 && q == 0) else $error("Fail at 15ns: state=%b q=%b", state, q);

        @(posedge clk); // 25ns
        #1;
        assert(state == 0 && q == 0) else $error("Fail at 25ns");

        @(posedge clk); // 35ns
        #1;
        assert(state == 0 && q == 0) else $error("Fail at 35ns");

        // 45ns posedge: a=0, b=1
        a = 0; b = 1;
        @(posedge clk); // 45ns
        #1;
        assert(state == 0 && q == 1) else $error("Fail at 45ns: state=%b q=%b", state, q);

        // 55ns posedge: a=1, b=0
        a = 1; b = 0;
        @(posedge clk); // 55ns
        #1;
        assert(state == 0 && q == 1) else $error("Fail at 55ns: state=%b q=%b", state, q);

        // 65ns posedge: a=1, b=1
        a = 1; b = 1;
        @(posedge clk); // 65ns
        #1;
        assert(state == 0 && q == 0) else $error("Fail at 65ns: state=%b q=%b", state, q);

        // 75ns posedge: a=0, b=0
        a = 0; b = 0;
        @(posedge clk); // 75ns
        #1;
        assert(state == 1 && q == 1) else $error("Fail at 75ns: state=%b q=%b", state, q);

        // 85ns posedge: a=1, b=1
        a = 1; b = 1;
        @(posedge clk); // 85ns
        #1;
        assert(state == 0 && q == 0) else $error("Fail at 85ns: state=%b q=%b", state, q);

        // 95ns posedge: a=1, b=1
        a = 1; b = 1;
        @(posedge clk); // 95ns
        #1;
        assert(state == 1 && q == 1) else $error("Fail at 95ns: state=%b q=%b", state, q);

        // 105ns posedge: a=1, b=1
        a = 1; b = 1;
        @(posedge clk); // 105ns
        #1;
        assert(state == 1 && q == 1) else $error("Fail at 105ns: state=%b q=%b", state, q);

        // 115ns posedge: a=1, b=0
        a = 1; b = 0;
        @(posedge clk); // 115ns
        #1;
        assert(state == 1 && q == 0) else $error("Fail at 115ns: state=%b q=%b", state, q);

        // 125ns posedge: a=0, b=1
        a = 0; b = 1;
        @(posedge clk); // 125ns
        #1;
        assert(state == 1 && q == 0) else $error("Fail at 125ns: state=%b q=%b", state, q);

        // 135ns posedge: a=0, b=0
        a = 0; b = 0;
        @(posedge clk); // 135ns
        #1;
        assert(state == 1 && q == 1) else $error("Fail at 135ns: state=%b q=%b", state, q);

        // 145ns posedge: a=0, b=0
        a = 0; b = 0;
        @(posedge clk); // 145ns
        #1;
        assert(state == 0 && q == 0) else $error("Fail at 145ns: state=%b q=%b", state, q);

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

